package work.solour.pulse;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
public class MainActivity extends Activity {
 static final int GREEN=Color.rgb(22,63,51),BG=Color.rgb(250,248,239),LIME=Color.rgb(213,249,157);LinearLayout root,live;TextView stats,status;Spinner scene,voice,goalType;EditText alert,rest,goal,manual;Switch sim;SessionService s;boolean bound=false,inReport=false;final Handler h=new Handler();
 final ServiceConnection conn=new ServiceConnection(){public void onServiceConnected(ComponentName n,IBinder b){s=((SessionService.Local)b).get();bound=true;if(s.e.running)training();else home();}public void onServiceDisconnected(ComponentName n){bound=false;s=null;}};
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);bindService(new Intent(this,SessionService.class),conn,BIND_AUTO_CREATE);h.post(update);}
 void page(String sub){inReport=false;ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(28,24,28,40);root.setBackgroundColor(BG);scroll.addView(root);setContentView(scroll);text("同频 PULSE",30);text(sub,15);}
 TextView text(String v,int size){TextView t=new TextView(this);t.setText(v);t.setTextColor(GREEN);t.setTextSize(size);t.setPadding(0,12,0,12);root.addView(t);return t;}
 void button(String name,Runnable r){Button b=new Button(this);b.setText(name);b.setTextColor(GREEN);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(LIME));root.addView(b,new LinearLayout.LayoutParams(-1,-2));b.setOnClickListener(v->r.run());}
 Spinner spinner(String label,String[] items){text(label,14);Spinner p=new Spinner(this);p.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,items));root.addView(p);return p;}
 EditText number(String label,String value){text(label,14);EditText e=new EditText(this);e.setSingleLine(true);e.setInputType(8194);e.setText(value);e.setTextColor(GREEN);root.addView(e);return e;}
 void note(String v){new AlertDialog.Builder(this).setMessage(v).setPositiveButton("知道了",null).show();}
 void home(){page("健身伴侣 1.1 · 给每一次坚持，一点回应");scene=spinner("今天想怎么动？",new String[]{"单车","跑步机","器械"});root.addView(new Art(this,"单车"),new LinearLayout.LayoutParams(-1,190));scene.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> a,View v,int p,long id){rest.setText(p==0?"60":p==1?"120":"90");}public void onNothingSelected(android.widget.AdapterView<?> a){}});
 sim=new Switch(this);sim.setText("模拟模式 · 演示数据（非真实测量）");sim.setTextColor(GREEN);root.addView(sim);voice=spinner("陪伴风格 · 系统离线中文 TTS",new String[]{"温柔陪伴","活力搭子","专业教练"});alert=number("心率警示参考值 BPM（不是通用安全阈值）","170");rest=number("休息秒数 · 30–600，可暂停和延长","60");goalType=spinner("训练目标（达到后只提醒）",new String[]{"时长（分钟）／器械组数","跑步机里程（公里）"});goal=number("目标：单车分钟 / 跑步分钟或公里 / 器械已确认组数；0 无目标","20");manual=number("跑步机手动速度 km/h · 无设备速度时估算，0 停止估算","0");button("开始训练",()->{try{int a=Integer.parseInt(alert.getText().toString()),r=Integer.parseInt(rest.getText().toString()),g=Integer.parseInt(goal.getText().toString());double m=Double.parseDouble(manual.getText().toString());if(a<60||a>240||r<30||r>600||g<0||!Double.isFinite(m)||m<0||m>30)throw new Exception();s.begin(scene.getSelectedItem().toString(),sim.isChecked(),a,r,g,goalType.getSelectedItemPosition()==1,voice.getSelectedItemPosition(),m);training();}catch(Exception e){note("请输入有效数值：警示60–240，休息30–600，目标非负整数，速度0–30。");}});button("最近100份本地报告",()->history());button("能力与使用说明",()->note("标准 BLE 心率180D/2A37，支持8/16位；可选RSC速度/步频与CSC踏频。华为、小米为适配目标，未验证全型号兼容。\n需要设备开放标准服务；厂商私有SDK未接入。无数据不会转为模拟。\n自动判组是未经实机验证的启发式，结果仅为推测；不推算次数、负重、力竭或动作质量。\n无需登录，无网络权限，不上传健康数据。个人曲库、云端大模型鼓励、真人音色未实现。\n离线中文语音依赖系统已安装的离线中文TTS语音包。来电/其他音频焦点丢失或耳机断开会暂停，需手动继续。\nAndroid系统可能终止进程；不会自动续训。请允许后台运行，避免强行停止。"));text("暖身、呼吸、按自己的节奏。",15);}
 void permissions(Runnable action){String[] p=Build.VERSION.SDK_INT>=31?new String[]{"android.permission.BLUETOOTH_SCAN","android.permission.BLUETOOTH_CONNECT"}:new String[]{"android.permission.ACCESS_FINE_LOCATION"};for(String x:p)if(checkSelfPermission(x)!=PackageManager.PERMISSION_GRANTED){requestPermissions(p,7);note("请授予蓝牙权限后再次扫描；Android 8–11 还需开启系统定位。");return;}action.run();}
 void training(){page(s.e.scene+" · "+(s.e.simulated?"模拟演示 · 非真实测量":"真实设备模式"));root.addView(new Art(this,s.e.scene),new LinearLayout.LayoutParams(-1,210));stats=text("",23);status=text("",14);button("暂停 / 继续训练",()->{if(s.e.paused)s.audio.request();s.pause();});button("音乐 开 / 关",()->{s.audio.music=!s.audio.music;});if(!s.e.simulated){button("扫描 BLE（10秒）",()->permissions(()->s.ble.scan()));button("选择已发现设备",()->{ArrayList<String> names=new ArrayList<>();for(android.bluetooth.BluetoothDevice d:s.ble.found)try{names.add((d.getName()==null?"未命名设备":d.getName())+"\n"+d.getAddress());}catch(SecurityException e){}if(names.isEmpty()){note("尚无设备；先扫描，并确保设备可连接且开放标准BLE服务。");return;}new AlertDialog.Builder(this).setTitle("标准BLE设备").setItems(names.toArray(new String[0]),(d,i)->s.ble.connect(i)).show();});}
 if(s.e.scene.equals("跑步机"))button("调整手动估算速度",()->inputSpeed());if(s.e.scene.equals("器械")){text("自动判组：未经实机验证的推测。确认后才计入目标。",14);button("手动开始本组",()->{if(s.e.paused||s.e.rest>0){note("请先继续训练并结束休息。");return;}if(s.e.groupStart>=0)note("当前已有一组，可完成或丢弃。");else s.e.startGroup(false);});button("手动完成当前组",()->{if(s.e.paused){note("请先继续训练。");return;}if(s.e.groupStart<0){note("当前没有进行中的组。");return;}s.e.finishGroup();if(!s.e.warning)s.audio.say("本组已记录，进入休息。",false);});button("丢弃未完成当前组",()->{s.e.groupStart=-1;s.e.rise=s.e.fall=0;});button("确认 / 删除组记录",()->groupList());}
 button(s.e.scene.equals("器械")?"开始组间休息":"开始主动恢复",()->{if(s.e.groupStart>=0){note("请先完成或丢弃当前组。");return;}s.e.startRest();});button("暂停 / 继续休息倒计时",()->s.e.restPaused=!s.e.restPaused);button("休息延长30秒（最多600秒）",()->s.e.rest=Math.min(600,s.e.rest+30));button("调整默认休息秒数",()->{EditText x=new EditText(this);x.setInputType(2);x.setText(""+s.e.restDefault);new AlertDialog.Builder(this).setTitle("30–600秒，下次休息生效").setView(x).setPositiveButton("保存",(d,w)->{try{int v=Integer.parseInt(x.getText().toString());if(v<30||v>600)throw new Exception();s.e.restDefault=v;}catch(Exception ex){note("休息必须为30–600秒");}}).setNegativeButton("取消",null).show();});button("提前结束休息（不开启下一组）",()->{s.e.rest=0;s.e.rise=s.e.fall=0;});button("结束训练并保存报告",()->new AlertDialog.Builder(this).setTitle("结束本次训练？").setMessage("未完成的当前组不会计为完成。推测组保留待确认标记。").setPositiveButton("结束并保存",(d,w)->{try{JSONObject r=s.finish();showReport(r);}catch(Exception ex){note("报告保存失败，训练尚未结束："+ex.getMessage());}}).setNegativeButton("继续训练",null).show());}
 void inputSpeed(){EditText x=new EditText(this);x.setInputType(8194);x.setText(""+s.e.manualKmh);new AlertDialog.Builder(this).setTitle("手动速度km/h · 明确为估算，0关闭").setView(x).setPositiveButton("保存",(d,w)->{try{double v=Double.parseDouble(x.getText().toString());if(!Double.isFinite(v)||v<0||v>30)throw new Exception();s.e.manualKmh=v;}catch(Exception e){note("请输入0–30");}}).setNegativeButton("取消",null).show();}
 void groupList(){String[] labels=new String[s.e.groups.size()];for(int i=0;i<labels.length;i++){Engine.Group g=s.e.groups.get(i);labels[i]="#"+(i+1)+" · "+g.duration+"秒 · "+(g.guessed?"推测 · ":"手动 · ")+(g.confirmed?"已确认":"待确认");}new AlertDialog.Builder(this).setTitle("组记录").setItems(labels,(d,i)->new AlertDialog.Builder(this).setItems(new String[]{"确认此组","删除此组"},(a,j)->{if(j==0){s.e.confirm(i);if(!s.e.warning)s.audio.say("已确认本组。"+s.audio.encouragement(),false);}else s.e.delete(i);}).show()).setNegativeButton("返回",null).show();}
 final Runnable update=new Runnable(){public void run(){if(bound&&s.e.running&&stats!=null&&!inReport){Engine e=s.e;long now=SystemClock.elapsedRealtime();stats.setText((e.paused?"已暂停 · ":"")+String.format(Locale.CHINA,"%02d:%02d",e.seconds/60,e.seconds%60)+"\n"+(e.freshHr(now)?e.hr+" BPM":"心率缺失 —")+(e.warning?"\n达到警示参考值 · 请降低强度":"")+"\n休息 "+e.rest+"秒"+(e.restPaused?" · 倒计时暂停":"")+(e.scene.equals("跑步机")?"\n"+String.format(Locale.CHINA,"%.3f km",e.distance/1000)+" · "+e.distanceLabel():e.scene.equals("器械")?"\n已确认 "+e.confirmed+"组 · 待确认 "+e.pending()+"组\n"+(e.groupStart>=0?(e.inferred?"推测组":"手动组")+"进行中 · "+(e.seconds-e.groupStart)+"秒":"基线有效秒 "+e.baseN+"/20"):"")+"\n"+(now-e.cadenceAt<=5000?(e.scene.equals("单车")?"踏频 ":"步频 ")+e.cadence:"步频 / 踏频缺失"));status.setText((e.simulated?"明确模拟模式":s.ble.status)+"\n"+s.audio.ttsStatus+"\n目标 "+s.target+(e.scene.equals("器械")?"组":s.distanceTarget?"公里":"分钟")+" · 音乐 "+new int[]{88,116,136}[e.band]+" BPM · "+(s.audio.music?"开启":"关闭"));}h.postDelayed(this,500);}};
 void history(){page("最近100份 · 仅保存在本机");JSONArray a=s.reports();for(int i=0;i<a.length();i++){final int index=i;JSONObject r=a.optJSONObject(i);button(new java.text.SimpleDateFormat("MM-dd HH:mm",Locale.CHINA).format(new Date(r.optLong("date")))+" · "+r.optString("scene")+(r.optBoolean("simulation")?" · 模拟":""),()->{showReport(r);button("删除这份报告",()->new AlertDialog.Builder(this).setMessage("删除后无法恢复").setPositiveButton("删除",(d,w)->{try{JSONArray all=s.reports();all.remove(index);s.save(all);history();}catch(Exception ex){note("删除失败");}}).setNegativeButton("取消",null).show());});}button("返回",()->home());}
 String val(JSONObject r,String key){return r.isNull(key)?"缺失":r.optString(key);}
 void showReport(JSONObject r){page("本次训练报告 · "+r.optString("scene"));inReport=true;text(r.optBoolean("simulation")?"模拟数据报告 · 不代表真实运动":"设备测量报告",21);text("时长 "+r.optInt("seconds")+"秒\n平均 / 最高心率 "+val(r,"avg")+" / "+val(r,"max")+" BPM\n有效心率数据覆盖 "+(r.optInt("seconds")==0?0:r.optInt("valid")*100/r.optInt("seconds"))+"%\n平均步频 / 踏频 "+val(r,"cadence"),19);if(r.optString("scene").equals("跑步机"))text("里程 "+r.optLong("metres")+"米 · "+r.optString("distanceLabel"),19);if(r.optString("scene").equals("器械")){text("已确认 "+r.optInt("confirmed")+"组 · 待确认 "+r.optInt("pending")+"组"+(r.optBoolean("unfinished")?"\n未完成当前组已排除":""),19);JSONArray a=r.optJSONArray("groups");for(int i=0;i<a.length();i++){JSONObject g=a.optJSONObject(i);text("#"+(i+1)+" 开始于"+g.optInt("start")+"秒 · "+g.optInt("duration")+"秒 · "+(g.optBoolean("guessed")?"推测 · ":"手动 · ")+(g.optBoolean("confirmed")?"已确认":"待确认"),15);}}
 text("心率曲线 · 横轴有效训练时间，缺失处断开",14);root.addView(new Chart(this,r.optJSONArray("curve")),new LinearLayout.LayoutParams(-1,250));button("报告列表",()->history());button("返回首页",()->home());}
 public void onBackPressed(){if(bound&&s.e.running)note("训练仍在前台服务运行；可返回训练页暂停或结束。");else if(bound)home();else super.onBackPressed();}
 public void onDestroy(){h.removeCallbacksAndMessages(null);if(bound)unbindService(conn);super.onDestroy();}
 class Chart extends View{JSONArray a;Paint p=new Paint(3);Chart(Context c,JSONArray a){super(c);this.a=a;}protected void onDraw(Canvas c){c.drawColor(LIME);p.setColor(GREEN);p.setStrokeWidth(3);p.setTextSize(24);c.drawText("250 BPM",8,25,p);c.drawText("25 BPM",8,getHeight()-10,p);if(a==null||a.length()<2)return;for(int i=1;i<a.length();i++){int v=a.optInt(i),prev=a.optInt(i-1);if(v>0&&prev>0)c.drawLine((i-1)*getWidth()/(float)(a.length()-1),getHeight()-(prev-25)*getHeight()/225f,i*getWidth()/(float)(a.length()-1),getHeight()-(v-25)*getHeight()/225f,p);}}}
 class Art extends View{String kind;Paint p=new Paint(3);Art(Context c,String k){super(c);kind=k;}protected void onDraw(Canvas c){float x=getWidth()/2f,y=getHeight()/2f,t=SystemClock.uptimeMillis()/500f;p.setColor(LIME);c.drawRoundRect(0,0,getWidth(),getHeight(),32,32,p);p.setColor(GREEN);p.setStrokeWidth(7);p.setStyle(Paint.Style.STROKE);if(kind.equals("单车")){c.drawCircle(x-60,y+25,35,p);c.drawCircle(x+60,y+25,35,p);c.drawLine(x-60,y+25,x,y-35,p);c.drawLine(x,y-35,x+60,y+25,p);c.drawLine(x-60,y+25,x+60,y+25,p);c.drawLine(x,y,x+(float)Math.cos(t)*22,y+(float)Math.sin(t)*22,p);}else if(kind.equals("跑步机")){c.drawLine(x-100,y+50,x+100,y+50,p);c.drawCircle(x,y-50,15,p);c.drawLine(x,y-35,x,y+5,p);float z=(float)Math.sin(t)*45;c.drawLine(x,y+5,x+z,y+40,p);c.drawLine(x,y+5,x-z,y+40,p);c.drawLine(x,y-20,x+z,y,p);}else{float z=(float)Math.sin(t)*20;c.drawLine(x-55,y+z,x+55,y+z,p);c.drawRect(x-80,y-30+z,x-55,y+30+z,p);c.drawRect(x+55,y-30+z,x+80,y+30+z,p);}p.setStyle(Paint.Style.FILL);postInvalidateDelayed(60);}}
}
